      await tester.pump();

      expect(find.text('Новость из кэша'), findsOneWidget);
      expect(find.text('Свежая новость'), findsNothing);

      networkCompleter.complete(freshItems);
      await tester.pumpAndSettle();

      expect(find.text('Свежая новость'), findsOneWidget);
      expect(find.text('Новость из кэша'), findsNothing);
    });

