      await tester.pumpAndSettle();

      expect(find.byType(NewsCard), findsNothing);
      expect(find.text('Новости пока недоступны'), findsOneWidget);
    });

    testWidgets('should keep cached news when the network request fails', (WidgetTester tester) async {
      when(mockNewsRepository.watchNewsFeed(any)).thenAnswer(
        (_) => NewsFeedPage(
          cached: Future<List<NewsModel>>.value(cachedItems),
          fresh: Future<List<NewsModel>>.error(Exception('network is down')),
        ),
      );

      await tester.pumpWidget(buildPage());
      await tester.pumpAndSettle();

      expect(find.text('Новость из кэша'), findsOneWidget);
    });
  });
}
