1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class NewsListPage extends StatefulWidget {
7:   const NewsListPage({super.key});
8: 
9:   @override
10:   State<NewsListPage> createState() => _NewsListPageState();
11: }
12: 
13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   List<NewsModel> _news = const [];
17:   bool _isCacheShown = false;
18:   bool _isCacheEmpty = false;
19: 
20:   late final AnimationController _scaleController;
21:   late final Animation<double> _scaleAnimation;
22: 
23:   @override
24:   void initState() {
25:     super.initState();
26:     _initAnimation();
27:     _initData();
28:   }
29: 
30:   @override
31:   void dispose() {
32:     _scaleController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _scaleController = AnimationController(
38:       vsync: this,
39:       duration: Duration(milliseconds: 200),
40:     );
41:     _scaleAnimation = _tween.animate(_scaleController);
42:   }
43: 
44:   void _initData() {
45:     final newsRepository = context.read<NewsRepository>();
46:     final NewsFeedPage feed = newsRepository.watchNewsFeed();
47: 
48:     // Кэш показываем сразу, как только он прочитан, не дожидаясь сети.
49:     feed.cached.then((List<NewsModel> cached) {
50:       if (!mounted) return;
51: 
52:       setState(() {
53:         _isCacheShown = true;
54:         _isCacheEmpty = cached.isEmpty;
55:         if (cached.isNotEmpty) _news = cached;
56:       });
57: 
58:       _scaleController.forward(); // запускаем анимацию
59:     });
60: 
61:     // Сеть догружается в фоне и перекрывает список, когда ответит.
62:     feed.fresh.then((List<NewsModel> fresh) {
63:       if (!mounted) return;
64: 
65:       setState(() {
66:         _isCacheShown = true;
67:         _isCacheEmpty = fresh.isEmpty;
68:         _news = fresh;
69:       });
70: 
71:       _scaleController.forward(); // запускаем анимацию
72:     }).catchError((Object _) {
73:       // Сеть недоступна — остаёмся на кэше, экран не ломается.
74:       if (!mounted) return;
75: 
76:       setState(() => _isCacheShown = true);
77:     });
78:   }
79: 
80:   @override
81:   Widget build(BuildContext context) {
82:     return Scaffold(
83:       appBar: AppBar(title: Text(context.loc.news)),
84:       body: ScaleTransition(
85:         scale: _scaleAnimation,
86:         child: _buildBody(),
87:       ),
88:     );
89:   }
90: 
91:   Widget _buildBody() {
92:     if (_news.isNotEmpty) return _buildNewsList();
93:     if (_isCacheShown) return _isCacheEmpty ? _buildEmptyState() : const SizedBox.shrink();
94: 
95:     return const SizedBox.shrink();
96:   }
97: 
98:   Widget _buildNewsList() {
99:     return ListView.builder(
100:       itemCount: _news.length,
101:       itemBuilder: (BuildContext context, int index) {
102:         final NewsModel news = _news[index];
103: 
104:         return Padding(
105:           key: ValueKey(news.link),
106:           padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
107:           child: NewsCard(model: news),
108:         );
109:       },
110:       padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
111:     );
112:   }
113: 
114:   Widget _buildEmptyState() {
115:     return Center(
116:       child: Padding(
117:         padding: const EdgeInsets.all(22),
118:         child: Text(
119:           context.loc.newsIsEmpty,
120:           textAlign: TextAlign.center,
121:           style: Theme.of(context).textTheme.bodyMedium,
122:         ),
123:       ),
124:     );
125:   }
126: }
